SELECT set_config('request.jwt.claim.role','service_role',TRUE);
SELECT pg_temp.admission_owner('00000000-0000-4000-8000-00000000f001');
CREATE FUNCTION pg_temp.media_create(scan UUID, vector BIGINT DEFAULT 3) RETURNS JSONB LANGUAGE SQL AS $$
 SELECT public.create_initial_preparation_intent('00000000-0000-4000-8000-00000000f001',scan,(SELECT internal.initial_canonical(v->'candidate') FROM media_vectors WHERE i=vector));
$$;
UPDATE internal.initial_analysis_rollout SET initial_analysis_lifecycle_enabled=TRUE;
-- Smaller synthetic wall caps fit the unchanged 300-second operation envelope.
UPDATE media_vectors SET v=jsonb_set(v,'{profile,spec,limits,wall_ms}','30000'::JSONB);
UPDATE media_vectors SET v=jsonb_set(v,'{profile,qualification,spec_digest}',to_jsonb(internal.initial_media_contract_digest('profile_spec',internal.initial_canonical(v#>'{profile,spec}'))));
UPDATE media_vectors SET v=jsonb_set(v,'{profile_canonical}',to_jsonb(internal.initial_canonical(v->'profile')));
UPDATE media_vectors SET v=jsonb_set(v,'{profile_digest}',to_jsonb(internal.initial_media_contract_digest('profile',v->>'profile_canonical')));
-- Synthetic transaction-local installation is not storage/runtime qualification.
INSERT INTO internal.initial_preparation_profiles SELECT v->>'profile_digest',v->>'profile_canonical' FROM media_vectors;
INSERT INTO internal.initial_preparation_installations(digest,target_kind,target_digest,evidence_digest,reviewed_revision,installer_protocol)
SELECT internal.initial_media_contract_digest('installation',internal.initial_canonical(value)),value->>'target_kind',value->>'target_digest',value->>'evidence_digest',value->>'reviewed_revision',value->>'installer_protocol' FROM (
 SELECT jsonb_build_object('target_kind','profile','target_digest',v->>'profile_digest','evidence_digest',v#>>'{profile,qualification,evidence_digest}','reviewed_revision',v#>>'{profile,qualification,source_revision}','installer_protocol','reviewed_database_owner_install_v1') value FROM media_vectors) x;
INSERT INTO internal.initial_preparation_profile_eligibility(profile_digest,installation_digest,state) SELECT target_digest,digest,'eligible' FROM internal.initial_preparation_installations WHERE target_kind='profile';
CREATE TEMP TABLE backend_fixture AS SELECT jsonb_build_object('generation','00000000-0000-4000-8000-00000000fb01','provider','r2','direct_endpoint','https://'||repeat('0',32)||'.r2.cloudflarestorage.com','private_bucket','synthetic-only','namespace','initial-preparation/v2','credential_profile','synthetic_only','storage_protocol','conditional_create_permanent_same_key_marker_v1') value;
INSERT INTO internal.initial_preparation_source_backends(generation,configuration_digest,provider,direct_endpoint,private_bucket,namespace,credential_profile,storage_protocol)
SELECT (value->>'generation')::UUID,internal.initial_media_contract_digest('backend',internal.initial_canonical(value)),value->>'provider',value->>'direct_endpoint',value->>'private_bucket',value->>'namespace',value->>'credential_profile',value->>'storage_protocol' FROM backend_fixture;
INSERT INTO internal.initial_preparation_installations(digest,target_kind,target_digest,evidence_digest,reviewed_revision,installer_protocol)
SELECT internal.initial_media_contract_digest('installation',internal.initial_canonical(value)),value->>'target_kind',value->>'target_digest',value->>'evidence_digest',value->>'reviewed_revision',value->>'installer_protocol' FROM (
 SELECT jsonb_build_object('target_kind','backend','target_digest',configuration_digest,'evidence_digest',repeat('a',64),'reviewed_revision',repeat('b',40),'installer_protocol','reviewed_database_owner_install_v1') value FROM internal.initial_preparation_source_backends) x;
INSERT INTO internal.initial_preparation_backend_eligibility(generation,configuration_digest,installation_digest,state) SELECT b.generation,b.configuration_digest,i.digest,'eligible' FROM internal.initial_preparation_source_backends b JOIN internal.initial_preparation_installations i ON i.target_kind='backend' AND i.target_digest=b.configuration_digest;
INSERT INTO internal.initial_preparation_selections(generation,profile_digest,backend_generation) SELECT ('00000000-0000-4000-8000-'||lpad((64000+i)::TEXT,12,'0'))::UUID,v->>'profile_digest','00000000-0000-4000-8000-00000000fb01' FROM media_vectors;
INSERT INTO internal.initial_preparation_current_selection SELECT v#>>'{profile,spec,input_profile}',s.generation FROM media_vectors JOIN internal.initial_preparation_selections s ON s.profile_digest=v->>'profile_digest';
CREATE FUNCTION pg_temp.funding_tripwire() RETURNS TRIGGER LANGUAGE PLPGSQL AS $$
BEGIN
 IF current_setting('merian.test_funding_tripwire',TRUE)='on' THEN
  IF TG_TABLE_NAME<>'users' THEN RAISE EXCEPTION 'synthetic_funding_mutation' USING ERRCODE='P0001'; END IF;
  IF NEW.complimentary_entitlement_epoch IS DISTINCT FROM OLD.complimentary_entitlement_epoch THEN
   RAISE EXCEPTION 'synthetic_funding_mutation' USING ERRCODE='P0001'; END IF;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END;
$$;
CREATE TRIGGER test_funding_tripwire BEFORE INSERT OR UPDATE OR DELETE ON internal.ai_quota_reservations FOR EACH ROW EXECUTE FUNCTION pg_temp.funding_tripwire();
CREATE TRIGGER test_funding_tripwire BEFORE INSERT OR UPDATE OR DELETE ON internal.ai_quota_counters FOR EACH ROW EXECUTE FUNCTION pg_temp.funding_tripwire();
CREATE TRIGGER test_funding_tripwire BEFORE INSERT OR UPDATE OR DELETE ON internal.complimentary_scan_usage FOR EACH ROW EXECUTE FUNCTION pg_temp.funding_tripwire();
CREATE TRIGGER test_funding_tripwire BEFORE INSERT OR UPDATE OR DELETE ON internal.identification_provider_attempts FOR EACH ROW EXECUTE FUNCTION pg_temp.funding_tripwire();
CREATE TRIGGER test_funding_tripwire BEFORE UPDATE ON public.users FOR EACH ROW EXECUTE FUNCTION pg_temp.funding_tripwire();
SELECT set_config('merian.test_funding_tripwire','on',TRUE);
CREATE FUNCTION pg_temp.source_receipt(scan UUID) RETURNS TEXT LANGUAGE PLPGSQL AS $$
DECLARE saved internal.initial_analysis_preparation_intents; a JSONB; profile JSONB; entries JSONB;
BEGIN
 SELECT * INTO STRICT saved FROM internal.initial_analysis_preparation_intents WHERE scan_id=scan;
 a:=saved.canonical_assignment::JSONB;
 SELECT canonical_profile::JSONB INTO STRICT profile FROM internal.initial_preparation_profiles WHERE digest=a#>>'{preparation,profile_digest}';
 SELECT jsonb_agg(jsonb_build_object('ordinal',e->'ordinal','object_id',e->'object_id','bytes',jsonb_build_object('byte_count',e#>'{source,source_byte_count}','sha256',e#>'{source,source_sha256}','content_type',e#>'{source,source_content_type}'),'facts',
 jsonb_build_object('image',CASE WHEN e#>>'{source,kind}'='image' THEN jsonb_build_object('width',1,'height',1,'format',split_part(e#>>'{source,source_content_type}','/',2)) END,
 'wav',CASE WHEN e#>>'{source,kind}'='audio' THEN jsonb_build_object('format','pcm16','sample_rate',16000,'channels',1,'frames',1) END,
 'mp4',CASE WHEN e#>>'{source,kind}'='video' THEN jsonb_build_object('structure','bounded_mp4_accepted') END)) ORDER BY i) INTO entries FROM jsonb_array_elements(a#>'{preparation,source_mapping}') WITH ORDINALITY v(e,i);
 RETURN internal.initial_canonical(jsonb_build_object('version',1,'scan_id',scan,'assignment_digest',saved.assignment_digest,'profile_digest',a#>>'{preparation,profile_digest}','backend_generation',a#>>'{preparation,backend_generation}','validator_identity',profile#>>'{spec,identities,validator}','entries',entries));
END; $$;
CREATE FUNCTION pg_temp.execution_advance(scan UUID,phase INTEGER) RETURNS JSONB LANGUAGE PLPGSQL AS $$
DECLARE saved internal.initial_analysis_preparation_intents; response JSONB; grant_value JSONB; entries JSONB; request JSONB; resolved JSONB; outcome JSONB; profile JSONB;
BEGIN
 SELECT * INTO STRICT saved FROM internal.initial_analysis_preparation_intents WHERE scan_id=scan;
 IF phase=0 THEN RETURN '{}'::JSONB; END IF;
 response:=public.settle_initial_preparation_sources(saved.owner_id,scan,saved.assignment_digest,pg_temp.source_receipt(scan));
 IF phase=1 THEN RETURN response; END IF;
 response:=public.issue_initial_preparation_execution(saved.owner_id,scan,saved.assignment_digest,response->>'digest');
 IF phase=2 THEN RETURN response; END IF;
 grant_value:=response->'grant';
 SELECT jsonb_agg(jsonb_build_object('ordinal',e->'ordinal','prepared',CASE WHEN e->>'role'<>'raw_video' THEN jsonb_build_object('bytes',jsonb_build_object('byte_count',CASE WHEN e#>>'{source,kind}'='audio' THEN '32'::JSONB ELSE e#>'{source,source_byte_count}' END,'sha256',CASE WHEN e#>>'{source,kind}'='audio' THEN repeat('7',64) ELSE e#>>'{source,source_sha256}' END,'content_type',e#>'{source,source_content_type}'),'transform',e#>'{source,transform}','parameters',e#>'{source,transform_parameters}','source_identity',e#>>'{source,kind}'<>'audio') END) ORDER BY i) INTO entries FROM jsonb_array_elements(saved.canonical_assignment::JSONB#>'{preparation,source_mapping}') WITH ORDINALITY v(e,i);
 request:=jsonb_build_object('version',1,'scan_id',scan,'assignment_digest',saved.assignment_digest,'grant_id',grant_value->'grant_id','source_digest',grant_value->'source_digest','entries',entries);
 IF phase=13 THEN RETURN request; END IF;
 response:=public.register_initial_preparation_output(saved.owner_id,scan,saved.assignment_digest,internal.initial_canonical(request));
 IF phase=3 THEN RETURN response; END IF;
 resolved:=response->'resolved';
 SELECT canonical_profile::JSONB INTO STRICT profile FROM internal.initial_preparation_profiles WHERE digest=saved.canonical_assignment::JSONB#>>'{preparation,profile_digest}';
 SELECT jsonb_agg(jsonb_build_object('ordinal',e->'ordinal','object_id',resolved#>ARRAY['entries',(i-1)::TEXT,'object_id'],'bytes',e#>'{prepared,bytes}') ORDER BY i) INTO entries FROM jsonb_array_elements(request->'entries') WITH ORDINALITY v(e,i) WHERE e->'prepared'<>'null'::JSONB;
 outcome:=jsonb_build_object('version',1,'scan_id',scan,'assignment_digest',saved.assignment_digest,'grant',grant_value,'source_verification',pg_temp.source_receipt(scan)::JSONB,'output_manifest',request,'resolved_manifest',resolved,'profile',profile,'retained',entries);
 IF phase=14 THEN RETURN outcome; END IF;
 RETURN public.settle_initial_preparation_outcome(saved.owner_id,scan,saved.assignment_digest,internal.initial_canonical(outcome));
END; $$;
-- Trusted clock fixture moves the entire coherent timeline together. Production
-- writers cannot perform these updates; actual expiry is still sampled after
-- a real blocking lock wait in the portable contention test.
CREATE FUNCTION pg_temp.age_execution(scan UUID) RETURNS VOID LANGUAGE PLPGSQL AS $$
DECLARE delta BIGINT; grant_value JSONB; key TEXT;
BEGIN
 SELECT floor(extract(epoch FROM (expires_at-clock_timestamp()))*1000)::BIGINT-400 INTO STRICT delta FROM internal.initial_analysis_preparation_intents WHERE scan_id=scan;
 ALTER TABLE internal.initial_analysis_preparation_intents DISABLE TRIGGER guard_initial_preparation_storage;
 ALTER TABLE internal.initial_preparation_execution_grants DISABLE TRIGGER guard_initial_execution_private;
 UPDATE internal.initial_analysis_preparation_intents SET created_at=created_at-delta*interval '1 millisecond',expires_at=expires_at-delta*interval '1 millisecond' WHERE scan_id=scan;
 SELECT canonical_grant::JSONB INTO grant_value FROM internal.initial_preparation_execution_grants WHERE scan_id=scan;
 IF grant_value IS NOT NULL THEN
  FOREACH key IN ARRAY ARRAY['issued_at_ms','execution_deadline_ms','registration_deadline_ms','outcome_deadline_ms'] LOOP
   grant_value:=jsonb_set(grant_value,ARRAY[key],to_jsonb((grant_value->>key)::BIGINT-delta));
  END LOOP;
  UPDATE internal.initial_preparation_execution_grants SET canonical_grant=internal.initial_canonical(grant_value) WHERE scan_id=scan;
 END IF;
 SET CONSTRAINTS ALL IMMEDIATE;
 ALTER TABLE internal.initial_analysis_preparation_intents ENABLE TRIGGER guard_initial_preparation_storage;
 ALTER TABLE internal.initial_preparation_execution_grants ENABLE TRIGGER guard_initial_execution_private;
END; $$;
CREATE TEMP TABLE execution_saved AS SELECT i,('00000000-0000-4000-8000-'||lpad((78000+i)::TEXT,12,'0'))::UUID scan,pg_temp.media_create(('00000000-0000-4000-8000-'||lpad((78000+i)::TEXT,12,'0'))::UUID,i) allocation FROM media_vectors;
SELECT extensions.is(pg_temp.execution_advance(scan,4)->>'outcome','outcome_ready','complete source/output/outcome cohort '||i) FROM execution_saved;
SET CONSTRAINTS ALL IMMEDIATE;
SET CONSTRAINTS ALL DEFERRED;
SELECT extensions.ok(internal.initial_preparation_execution_coherent(scan),'deferred full cohort integrity '||i) FROM execution_saved;
SELECT extensions.ok(internal.can_cancel_initial_preparation('00000000-0000-4000-8000-00000000f001',scan),'issued outcome has positive no-provider proof '||i) FROM execution_saved;
SELECT extensions.is(public.get_initial_preparation_status('00000000-0000-4000-8000-00000000f001',scan),allocation,'old metadata reader remains exact after issue '||i) FROM execution_saved;
SELECT extensions.is(public.issue_initial_preparation_execution('00000000-0000-4000-8000-00000000f001',s.scan,s.allocation->>'assignment_digest',v.digest)->>'reason','preparation_issued','second issue never returns grant '||s.i) FROM execution_saved s JOIN internal.initial_preparation_source_verifications v ON v.scan_id=s.scan;
SELECT extensions.is(public.register_initial_preparation_output('00000000-0000-4000-8000-00000000f001',s.scan,s.allocation->>'assignment_digest',m.canonical_request)->'resolved',m.canonical_resolved::JSONB,'lost output reply recovers exact IDs '||s.i) FROM execution_saved s JOIN internal.initial_preparation_output_manifests m ON m.scan_id=s.scan;
SELECT extensions.is(public.settle_initial_preparation_outcome('00000000-0000-4000-8000-00000000f001',s.scan,s.allocation->>'assignment_digest',o.canonical_outcome)->'result',o.canonical_outcome::JSONB,'lost outcome reply recovers full proof '||s.i) FROM execution_saved s JOIN internal.initial_preparation_outcomes o ON o.scan_id=s.scan;
SELECT extensions.is((SELECT count(*) FROM internal.ai_quota_reservations WHERE user_id='00000000-0000-4000-8000-00000000f001'),0::BIGINT,'preparation cannot fund');
SELECT extensions.throws_ok(format('SELECT public.finalize_initial_preparation(%L,%L,NULL)','00000000-0000-4000-8000-00000000f001',scan),'55000','initial_analysis_preparation_required','outcome cannot finalize media admission '||i) FROM execution_saved;
SELECT extensions.throws_ok(format('SELECT internal.reject_initial_preparation_provider_writer(ARRAY[%L::UUID])',scan),'55000','initial_analysis_preparation_provider_blocked','positive provider barrier denies every competitor helper '||i) FROM execution_saved;
SELECT extensions.throws_ok(format('SELECT internal.lock_initial_media_scope(%L,%L,%L)','00000000-0000-4000-8000-00000000f001',scan,repeat('a',64)),'55000','initial_analysis_preparation_provider_blocked','M1/M2 scope explicitly rejects barrier '||i) FROM execution_saved;
SELECT extensions.throws_ok(format('INSERT INTO internal.initial_analysis_media_preparations(scan_id) VALUES(%L)',scan),'55000','initial_analysis_preparation_provider_blocked','raw M2 insert denied before other constraints '||i) FROM execution_saved;
SELECT extensions.throws_ok(format('INSERT INTO internal.ai_quota_reservations(request_id) VALUES(%L)',scan),'55000','initial_analysis_preparation_provider_blocked','raw quota insert denied before funding '||i) FROM execution_saved;
SELECT extensions.throws_ok(format('INSERT INTO internal.identification_invocations(scan_id) VALUES(%L)',scan),'55000','initial_analysis_preparation_provider_blocked','raw provider insert denied '||i) FROM execution_saved;
SELECT extensions.throws_ok(format('UPDATE internal.initial_preparation_source_fences SET provider_barrier=NULL WHERE scan_id=%L',scan),'22023','initial_analysis_storage_immutable','barrier cannot clear '||i) FROM execution_saved;
SELECT extensions.throws_ok(format('UPDATE internal.initial_preparation_source_fences SET execution_state=''unissued'' WHERE scan_id=%L',scan),'22023','initial_analysis_storage_immutable','issued bit cannot reopen '||i) FROM execution_saved;
SELECT extensions.ok(NOT(public.get_initial_preparation_execution_status('00000000-0000-4000-8000-00000000f001',scan,allocation->>'assignment_digest') ? 'grant'),'status has no standalone grant '||i) FROM execution_saved;
SELECT extensions.is((SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(public.get_initial_preparation_execution_status('00000000-0000-4000-8000-00000000f001',scan,allocation->>'assignment_digest')->'execution_reference') k),ARRAY['grant_id','source_digest'],'status reference has no deadlines '||i) FROM execution_saved;
SELECT extensions.is((g.canonical_grant::JSONB->>'execution_deadline_ms')::BIGINT-(g.canonical_grant::JSONB->>'issued_at_ms')::BIGINT-5000,
 internal.initial_preparation_cohort_wall(i.canonical_assignment::JSONB,p.canonical_profile::JSONB),'actual role wall sum '||s.i)
 FROM execution_saved s JOIN internal.initial_preparation_execution_grants g ON g.scan_id=s.scan JOIN internal.initial_analysis_preparation_intents i ON i.scan_id=s.scan JOIN internal.initial_preparation_profiles p ON p.digest=i.canonical_assignment::JSONB#>>'{preparation,profile_digest}';
SELECT extensions.throws_ok(format('SELECT internal.checked_initial_preparation_reply(%L::JSONB)',public.get_initial_preparation_execution_status('00000000-0000-4000-8000-00000000f001',scan,allocation->>'assignment_digest')||'{"grant":null}'::JSONB),'22023','initial_analysis_input_invalid','SQL schema rejects grant leak '||i) FROM execution_saved;
-- Exercise the actual M2 public owners, including its side-effecting read path.
SELECT extensions.throws_ok(format('SELECT public.claim_initial_media_preparation(%L,%L,%L,%L)','00000000-0000-4000-8000-00000000f001',scan,repeat('a',64),repeat('b',64)),'55000','initial_analysis_preparation_provider_blocked','M2 claim denied '||i) FROM execution_saved;
SELECT extensions.throws_ok(format('SELECT public.settle_initial_media_verification(%L,%L,%L,%L,%L)','00000000-0000-4000-8000-00000000f001',scan,repeat('a',64),repeat('b',64),'00000000-0000-4000-8000-00000000a001'),'55000','initial_analysis_preparation_provider_blocked','M2 settle denied '||i) FROM execution_saved;
SELECT extensions.throws_ok(format('SELECT public.get_initial_media_verification(%L,%L,%L,%L)','00000000-0000-4000-8000-00000000f001',scan,repeat('a',64),repeat('b',64)),'55000','initial_analysis_preparation_provider_blocked','M2 status denied '||i) FROM execution_saved;
SELECT extensions.ok(NOT internal.can_cancel_initial_preparation('00000000-0000-4000-8000-00000000ffff',scan),'wrong owner cannot prove C1 '||i) FROM execution_saved;
SET CONSTRAINTS ALL IMMEDIATE;
SET CONSTRAINTS ALL DEFERRED;
-- Deliberately damage private fixtures inside rolled-back subtransactions. This
-- is a trusted database-owner corruption probe, never a permitted writer path.
CREATE FUNCTION pg_temp.damaged_proof_denied(scan UUID,damage TEXT) RETURNS BOOLEAN LANGUAGE PLPGSQL AS $$
DECLARE accepted BOOLEAN; changed TEXT;
BEGIN
 BEGIN
  IF damage='missing_source' THEN
   ALTER TABLE internal.initial_preparation_source_verifications DISABLE TRIGGER guard_initial_execution_private;
   DELETE FROM internal.initial_preparation_source_verifications WHERE scan_id=scan;
  ELSIF damage='missing_grant' THEN
   ALTER TABLE internal.initial_preparation_execution_grants DISABLE TRIGGER guard_initial_execution_private;
   DELETE FROM internal.initial_preparation_execution_grants WHERE scan_id=scan;
  ELSIF damage='changed_grant' THEN
   ALTER TABLE internal.initial_preparation_execution_grants DISABLE TRIGGER guard_initial_execution_private;
   UPDATE internal.initial_preparation_execution_grants SET canonical_grant=internal.initial_canonical(jsonb_set(canonical_grant::JSONB,'{source_digest}',to_jsonb(repeat('9',64)))) WHERE scan_id=scan;
  ELSIF damage='missing_output_mapping' THEN
   ALTER TABLE internal.initial_preparation_output_mapping DISABLE TRIGGER guard_initial_execution_private;
   DELETE FROM internal.initial_preparation_output_mapping WHERE scan_id=scan;
  ELSIF damage='crossed_request' THEN
   ALTER TABLE internal.initial_preparation_output_manifests DISABLE TRIGGER guard_initial_execution_private;
   SELECT internal.initial_canonical(jsonb_set(canonical_request::JSONB,'{grant_id}','"00000000-0000-4000-8000-00000000c001"')) INTO changed FROM internal.initial_preparation_output_manifests WHERE scan_id=scan;
   UPDATE internal.initial_preparation_output_manifests SET canonical_request=changed,request_digest=internal.initial_preparation_execution_digest('output_manifest',changed) WHERE scan_id=scan;
  ELSIF damage='crossed_alias' THEN
   ALTER TABLE internal.initial_preparation_output_manifests DISABLE TRIGGER guard_initial_execution_private;
   UPDATE internal.initial_preparation_output_manifests SET canonical_resolved=internal.initial_canonical(jsonb_set(canonical_resolved::JSONB,'{entries,0,object_id}','"00000000-0000-4000-8000-00000000c002"')) WHERE scan_id=scan;
  ELSIF damage='extra_registry' THEN
   INSERT INTO internal.initial_preparation_source_registry(object_id,scan_id,backend_generation) SELECT gen_random_uuid(),scan,backend_generation FROM internal.initial_preparation_source_registry WHERE scan_id=scan LIMIT 1;
  ELSIF damage='missing_barrier' THEN
   ALTER TABLE internal.initial_preparation_source_fences DISABLE TRIGGER guard_initial_preparation_source_fence;
   UPDATE internal.initial_preparation_source_fences SET provider_barrier=NULL WHERE scan_id=scan;
  ELSE RAISE EXCEPTION 'unrecognized damage case'; END IF;
  accepted:=internal.can_cancel_initial_preparation('00000000-0000-4000-8000-00000000f001',scan);
  BEGIN
   INSERT INTO internal.initial_analysis_lifecycle_fences(scan_id,state) VALUES(scan,'cancelled_pre_dispatch');
   accepted:=TRUE; -- Both predicate and actual raw cancellation guard must deny.
  EXCEPTION WHEN invalid_parameter_value OR object_not_in_prerequisite_state THEN NULL;
  END;
  RAISE SQLSTATE 'ZX001';
 EXCEPTION WHEN SQLSTATE 'ZX001' THEN RETURN NOT accepted;
 END;
END; $$;
SELECT extensions.ok(pg_temp.damaged_proof_denied(scan,damage),'damaged proof denies positive C1 '||i||'/'||damage)
FROM execution_saved CROSS JOIN unnest(ARRAY['missing_source','missing_grant','changed_grant','missing_output_mapping','crossed_request','crossed_alias','extra_registry','missing_barrier']) damage;
SELECT extensions.ok(internal.can_cancel_initial_preparation('00000000-0000-4000-8000-00000000f001',scan),'damage fixtures fully rolled back '||i) FROM execution_saved;
CREATE FUNCTION pg_temp.raw_c1_probe(scan UUID) RETURNS BOOLEAN LANGUAGE PLPGSQL AS $$
BEGIN
 BEGIN
  INSERT INTO internal.initial_analysis_lifecycle_fences(scan_id,state) VALUES(scan,'cancelled_pre_dispatch');
  RAISE SQLSTATE 'ZX002';
 EXCEPTION WHEN SQLSTATE 'ZX002' THEN RETURN TRUE;
 END;
END; $$;
-- Current selector changes cannot replace the saved assignment for first issue.
SELECT pg_temp.media_create('00000000-0000-4000-8000-000000079201',3)->>'outcome';
SELECT pg_temp.execution_advance('00000000-0000-4000-8000-000000079201',1)->>'outcome';
SAVEPOINT selection_change;
DELETE FROM internal.initial_preparation_current_selection;
SELECT extensions.is(pg_temp.execution_advance('00000000-0000-4000-8000-000000079201',2)->>'outcome','granted','first issuance uses saved eligible profile after current selector removal');
SELECT extensions.is((SELECT canonical_grant::JSONB->>'profile_digest' FROM internal.initial_preparation_execution_grants WHERE scan_id='00000000-0000-4000-8000-000000079201'),(SELECT canonical_assignment::JSONB#>>'{preparation,profile_digest}' FROM internal.initial_analysis_preparation_intents WHERE scan_id='00000000-0000-4000-8000-000000079201'),'first issuance preserves saved profile digest');
ROLLBACK TO selection_change;
RELEASE SAVEPOINT selection_change;
SELECT public.cancel_initial_analysis('00000000-0000-4000-8000-00000000f001','00000000-0000-4000-8000-000000079201');
-- An unexpired but inadequate original budget holds before issuing any grant.
SELECT pg_temp.media_create('00000000-0000-4000-8000-000000079202',3)->>'outcome';
SELECT pg_temp.execution_advance('00000000-0000-4000-8000-000000079202',1)->>'outcome';
SET CONSTRAINTS ALL IMMEDIATE;
ALTER TABLE internal.initial_analysis_preparation_intents DISABLE TRIGGER guard_initial_preparation_storage;
UPDATE internal.initial_analysis_preparation_intents SET created_at=statement_timestamp()-interval '240 seconds',expires_at=statement_timestamp()+interval '60 seconds' WHERE scan_id='00000000-0000-4000-8000-000000079202';
ALTER TABLE internal.initial_analysis_preparation_intents ENABLE TRIGGER guard_initial_preparation_storage;
SET CONSTRAINTS ALL DEFERRED;
SELECT extensions.is(pg_temp.execution_advance('00000000-0000-4000-8000-000000079202',2)->>'reason','budget','insufficient original remaining budget holds before grant');
SELECT extensions.is((SELECT execution_state FROM internal.initial_preparation_source_fences WHERE scan_id='00000000-0000-4000-8000-000000079202'),'unissued','budget hold never consumes issued bit');
SELECT extensions.is((SELECT count(*) FROM internal.initial_preparation_execution_grants WHERE scan_id='00000000-0000-4000-8000-000000079202'),0::BIGINT,'budget hold creates no private grant');
SELECT public.cancel_initial_analysis('00000000-0000-4000-8000-00000000f001','00000000-0000-4000-8000-000000079202');
-- Each coherent stage independently cancels before registry retirement.
CREATE TEMP TABLE execution_phases AS SELECT n,('00000000-0000-4000-8000-'||lpad((79000+n)::TEXT,12,'0'))::UUID scan,pg_temp.media_create(('00000000-0000-4000-8000-'||lpad((79000+n)::TEXT,12,'0'))::UUID,3) allocation FROM generate_series(0,4) n;
SELECT pg_temp.execution_advance(scan,n)->>'outcome' FROM execution_phases;
SET CONSTRAINTS ALL IMMEDIATE;
SET CONSTRAINTS ALL DEFERRED;
SELECT extensions.ok(pg_temp.raw_c1_probe(scan),'raw lifecycle phase-aware C1 '||n) FROM execution_phases;
SELECT extensions.is(public.cancel_initial_analysis('00000000-0000-4000-8000-00000000f001',scan)->>'dispatch','dispatch_prevented','phase-aware C1 '||n) FROM execution_phases;
SET CONSTRAINTS ALL IMMEDIATE;
SET CONSTRAINTS ALL DEFERRED;
SELECT extensions.ok(NOT EXISTS(SELECT 1 FROM internal.initial_analysis_preparation_intents WHERE scan_id=p.scan),'C1 erases private receipt parent '||n) FROM execution_phases p;
SELECT extensions.ok(NOT EXISTS(SELECT 1 FROM internal.initial_preparation_source_registry WHERE scan_id=p.scan AND NOT retired),'C1 retires complete source/output union '||n) FROM execution_phases p;
SELECT extensions.is((SELECT provider_barrier FROM internal.initial_preparation_source_fences WHERE scan_id=p.scan),'blocked_pre_admission','C1 preserves content-free prohibition '||n) FROM execution_phases p;
-- Existing rows retain read and conservative erasure; this fixture simulates pre-migration NULL only.
SELECT pg_temp.media_create('00000000-0000-4000-8000-000000079100',3)->>'outcome';
SET CONSTRAINTS ALL IMMEDIATE;
ALTER TABLE internal.initial_preparation_source_fences DISABLE TRIGGER guard_initial_preparation_source_fence;
UPDATE internal.initial_preparation_source_fences SET provider_barrier=NULL WHERE scan_id='00000000-0000-4000-8000-000000079100';
ALTER TABLE internal.initial_preparation_source_fences ENABLE TRIGGER guard_initial_preparation_source_fence;
SET CONSTRAINTS ALL DEFERRED;
SELECT extensions.is(public.get_initial_preparation_status('00000000-0000-4000-8000-00000000f001','00000000-0000-4000-8000-000000079100')->>'outcome','allocated','marker-less row reads exact original metadata');
SELECT extensions.is(public.cancel_initial_analysis('00000000-0000-4000-8000-00000000f001','00000000-0000-4000-8000-000000079100')->>'dispatch','dispatch_outcome_unknown','marker-less C1 remains conservative');
SET CONSTRAINTS ALL IMMEDIATE;
SET CONSTRAINTS ALL DEFERRED;
-- Revocation preserves original known-result recovery, never new authority.
UPDATE internal.initial_preparation_profile_eligibility SET state='revoked';
SELECT extensions.is(public.settle_initial_preparation_sources('00000000-0000-4000-8000-00000000f001',s.scan,s.allocation->>'assignment_digest',v.canonical_receipt)->>'outcome','verified','saved source proof before current eligibility '||s.i) FROM execution_saved s JOIN internal.initial_preparation_source_verifications v ON v.scan_id=s.scan;
SELECT extensions.is(public.settle_initial_preparation_outcome('00000000-0000-4000-8000-00000000f001',s.scan,s.allocation->>'assignment_digest',o.canonical_outcome)->>'outcome','outcome_ready','original outcome survives revocation '||s.i) FROM execution_saved s JOIN internal.initial_preparation_outcomes o ON o.scan_id=s.scan;
SELECT extensions.ok(NOT has_table_privilege(role_name,'internal.'||table_name,privilege),'private execution role denial '||role_name||'/'||table_name||'/'||privilege)
FROM unnest(ARRAY['anon','authenticated','service_role']) role_name CROSS JOIN unnest(ARRAY['SELECT','INSERT','UPDATE','DELETE']) privilege CROSS JOIN unnest(ARRAY['initial_preparation_source_verifications','initial_preparation_execution_grants','initial_preparation_output_manifests','initial_preparation_output_mapping','initial_preparation_outcomes']) table_name;
SELECT * FROM extensions.finish();
ROLLBACK;
